        getFloatValueInternal(fieldArrayIndex, getSubField(subFieldName))

    protected fun getFloatValueInternal(fieldArrayIndex: Int, subField: SubField?): Float? {
        val value = getValueInternal(fieldArrayIndex, subField) ?: return null

        return (value as Number).toDouble().toFloat()
    }

    val doubleValues: Array<Double>
        get() = getDoubleValues(null as SubField?)

    fun getDoubleValues(subfieldIndex: Int): Array<Double> =
        getDoubleValues(getSubField(subfieldIndex))

    fun getDoubleValues(subFieldName: String?): Array<Double> =
        getDoubleValues(getSubField(subFieldName))

    protected fun getDoubleValues(subfield: SubField?): Array<Double> =
        (0 until numValues).mapNotNull {
            getDoubleValueInternal(it, subfield)
        }.toTypedArray()

    val doubleValue: Double?
        get() = getDoubleValueInternal(0, null)

    fun getDoubleValue(fieldArrayIndex: Int): Double? =
        getDoubleValueInternal(fieldArrayIndex, null)

    fun getDoubleValue(fieldArrayIndex: Int, subFieldIndex: Int): Double? =
        getDoubleValueInternal(fieldArrayIndex, getSubField(subFieldIndex))

    fun getDoubleValue(fieldArrayIndex: Int, subFieldName: String?): Double? =
        getDoubleValueInternal(fieldArrayIndex, getSubField(subFieldName))

    protected fun getDoubleValueInternal(fieldArrayIndex: Int, subField: SubField?): Double? {
        val value = getValueInternal(fieldArrayIndex, subField) ?: return null

        return (value as Number).toDouble()
    }

    val stringValues: Array<String?>
        get() = getStringValues(null as SubField?)

    fun getStringValues(subfieldIndex: Int): Array<String?> =
        getStringValues(getSubField(subfieldIndex))

    fun getStringValues(subFieldName: String?): Array<String?> =
        getStringValues(getSubField(subFieldName))

    protected fun getStringValues(subfield: SubField?): Array<String?> {
        val rv = arrayOfNulls<String>(this.numValues)

        for (i in 0..<this.numValues) {
            rv[i] = getStringValueInternal(i, subfield)
        }

        return rv
    }

    val stringValue: String?
        get() = getStringValueInternal(0, null)

    fun getStringValue(fieldArrayIndex: Int): String? =
        getStringValueInternal(fieldArrayIndex, null)

    fun getStringValue(fieldArrayIndex: Int, subFieldIndex: Int): String? =
        getStringValueInternal(fieldArrayIndex, getSubField(subFieldIndex))

    fun getStringValue(fieldArrayIndex: Int, subFieldName: String?): String? =
        getStringValueInternal(fieldArrayIndex, getSubField(subFieldName))

    protected fun getStringValueInternal(fieldArrayIndex: Int, subField: SubField?): String? {
        val value = getValueInternal(fieldArrayIndex, subField)
        val type = getTypeInternal(subField)

        if (value == null) {
            return null
        }

        if (!forceShowInvalids && Fit.baseTypeInvalidMap[type] == value) {
            return null
        }

        return value.toString()
    }

    fun read(inputStream: InputStream, size: Int): Boolean {
        try {
            val data = DataInputStream(inputStream)
            if (this.type == Fit.BASE_TYPE_STRING) {
                try {
                    val bytes = ByteArray(size)
                    inputStream.read(bytes, 0, size)
                    val byteBuffer = ByteBuffer.wrap(bytes)

                    val utf8Decoder = Charset.forName("UTF-8").newDecoder()
                    utf8Decoder.onMalformedInput(CodingErrorAction.IGNORE)
                    utf8Decoder.onUnmappableCharacter(CodingErrorAction.IGNORE)

                    utf8Decoder.decode(byteBuffer)
                        .toString()
                        .split("\u0000".toRegex())
                        .dropLastWhile { it.isEmpty() }
                        .forEach { values.add(it) }
                } catch (e: IOException) {
                    return true
                }
            } else {
                var bytesLeft = size
                var invalid = true

                val type = this.type
                val baseTypeSize = Fit.baseTypeSizes[type and Fit.BASE_TYPE_NUM_MASK]

                while (bytesLeft > 0) {
                    var value: Any?
                    when (type) {
                        Fit.BASE_TYPE_ENUM, Fit.BASE_TYPE_UINT8, Fit.BASE_TYPE_UINT8Z ->
                            value = (data.readByte().toInt() and 0xFF).toShort()

                        Fit.BASE_TYPE_SINT8 -> value = data.readByte()

                        Fit.BASE_TYPE_SINT16 -> value = data.readShort()

                        Fit.BASE_TYPE_UINT16, Fit.BASE_TYPE_UINT16Z -> {
                            value = data.readByte().toInt() and 0xFF
                            value = value shl 8
                            value = value or (data.readByte().toInt() and 0xFF)
                        }

                        Fit.BASE_TYPE_SINT32 -> value = data.readInt()

                        Fit.BASE_TYPE_UINT32, Fit.BASE_TYPE_UINT32Z, Fit.BASE_TYPE_SINT64 -> {
                            value = (data.readByte().toInt() and 0xFF).toLong()
                            var i = 1
                            while (i < baseTypeSize) {
                                value = (value as Long) shl 8
                                value = value or (data.readByte().toInt() and 0xFF).toLong()
                                i++
                            }
                        }

                        Fit.BASE_TYPE_FLOAT32 -> value = data.readFloat()

                        Fit.BASE_TYPE_FLOAT64 -> value = data.readDouble()

                        Fit.BASE_TYPE_BYTE -> value = (data.readByte().toInt() and 0xFF).toShort()

                        Fit.BASE_TYPE_UINT64, Fit.BASE_TYPE_UINT64Z -> value =
                            data.readLong().toULong()

                        else -> return false
                    }

                    values.add(value)

                    if (value != invalidValue) invalid = false


                    bytesLeft -= Fit.baseTypeSizes[this.type and Fit.BASE_TYPE_NUM_MASK]
                }

                if (invalid && !forceShowInvalids) {
                    values.clear()
                }
            }
        } catch (e: IOException) {
            return false
        }

        return true
    }

    fun write(out: OutputStream, fieldDef: FieldDefinitionBase) {
        var bytesLeft = fieldDef.size - this.size

        write(out)

        // Fill remaining bytes with invalid.
        while (bytesLeft > 0) {
            writeValue(out, null)
            bytesLeft -= Fit.baseTypeSizes[this.type and Fit.BASE_TYPE_NUM_MASK]
        }
    }

    protected fun write(out: OutputStream) {
        for (value in values) {
            writeValue(out, value)
        }
    }

    private fun writeValue(out: OutputStream, value: Any?) {
        try {
            val data = DataOutputStream(out)

            if (value == null) {
                when (this.type) {
                    Fit.BASE_TYPE_ENUM -> data.writeByte(Fit.ENUM_INVALID.toInt())
                    Fit.BASE_TYPE_UINT8 -> data.writeByte(Fit.UINT8_INVALID.toInt())
                    Fit.BASE_TYPE_UINT8Z -> data.writeByte(Fit.UINT8Z_INVALID.toInt())
                    Fit.BASE_TYPE_SINT8 -> data.writeByte(Fit.SINT8_INVALID.toInt())
                    Fit.BASE_TYPE_BYTE -> data.writeByte(Fit.BYTE_INVALID.toInt())
                    Fit.BASE_TYPE_SINT16 -> data.writeShort(Fit.SINT16_INVALID.toInt())
                    Fit.BASE_TYPE_UINT16 -> data.writeShort(Fit.UINT16_INVALID)
                    Fit.BASE_TYPE_UINT16Z -> data.writeShort(Fit.UINT16Z_INVALID)
                    Fit.BASE_TYPE_SINT32 -> data.writeInt(Fit.SINT32_INVALID)
                    Fit.BASE_TYPE_UINT32 -> data.writeInt(Fit.UINT32_INVALID.toInt())
                    Fit.BASE_TYPE_UINT32Z -> data.writeInt(Fit.UINT32Z_INVALID.toInt())
                    Fit.BASE_TYPE_SINT64 -> data.writeLong(Fit.SINT64_INVALID)
                    Fit.BASE_TYPE_UINT64 -> data.writeLong(Fit.UINT64_INVALID.toLong())
                    Fit.BASE_TYPE_UINT64Z -> data.writeLong(Fit.UINT64Z_INVALID.toLong())
                    Fit.BASE_TYPE_STRING -> data.writeByte(0)
                    Fit.BASE_TYPE_FLOAT32 -> data.writeFloat(Fit.FLOAT32_INVALID)
                    Fit.BASE_TYPE_FLOAT64 -> data.writeDouble(Fit.FLOAT64_INVALID)
                }
            } else { // if (value != null)
                when (this.type) {
                    Fit.BASE_TYPE_ENUM,
                    Fit.BASE_TYPE_UINT8, Fit.BASE_TYPE_UINT8Z,
                    Fit.BASE_TYPE_SINT8, Fit.BASE_TYPE_BYTE -> {
                        if (value is String) {
                            System.err.printf(
                                "Field.write(): Field %s value should not be string value %s\n",
                                this.fieldName, value
                            )
                        }
//                        println("Write byte for value=$value, data=${(value as Number).toDouble().roundToLong().toInt()}")
                        data.writeByte((value as Number).toDouble().roundToLong().toInt())
                    }

                    Fit.BASE_TYPE_SINT16, Fit.BASE_TYPE_UINT16, Fit.BASE_TYPE_UINT16Z ->
                        data.writeShort((value as Number).toDouble().roundToLong().toInt())

                    Fit.BASE_TYPE_SINT32, Fit.BASE_TYPE_UINT32, Fit.BASE_TYPE_UINT32Z ->
                        data.writeInt((value as Number).toDouble().roundToLong().toInt())

                    Fit.BASE_TYPE_STRING -> {
                        val stringWriter = OutputStreamWriter(out, "UTF-8")
                        stringWriter.write(value.toString())
                        stringWriter.flush()
                        out.write(0)
                    }

                    Fit.BASE_TYPE_FLOAT32 -> data.writeFloat((value as Number).toFloat())
                    Fit.BASE_TYPE_FLOAT64 -> data.writeDouble((value as Number).toDouble())
                    Fit.BASE_TYPE_SINT64 -> data.writeLong(
                        value as? Long
                            ?: (value as Number)
                                .toDouble()
                                .roundToLong()
                    )

                    Fit.BASE_TYPE_UINT64, Fit.BASE_TYPE_UINT64Z -> when (value) {
                        is Long -> data.writeLong(value)
                        is ULong -> data.writeLong(value.toLong())
                        is Number -> data.writeLong(round(value.toDouble()).toULong().toLong())
                    }
                }
            } // if (value != null)
        } catch (e: IOException) {
        }
    }

    override fun toString() = "FieldBase(" +
            "fieldName=$fieldName, " +
            "name=$name, " +
            "type=$type, " +
            "typeName=${typeString(type)}, " +
            "units=$units, " +
            "numValues=$numValues, " +
            "values=$values, " +
            "rawValue=$rawValue, " +
            "scale=$scale, " +
            "offset=$offset, " +
            "size=$size, " +
            "isValid=$isValid" +
            ")"

    companion object {
        @JvmField
        var forceShowInvalids: Boolean = !Fit.ENABLE_LEGACY_BEHAVIOUR

        fun typeString(type: Int) = typeString(type.toShort())
        fun typeString(type: Short) = FitBaseType.getStringFromValue(type)
    }
}
